CREATE TABLE public.farm_members (owner_id uuid NOT NULL, user_id uuid NOT NULL, role text NOT NULL DEFAULT 'manager' CHECK(role='manager'), PRIMARY KEY(owner_id,user_id));
GRANT SELECT ON public.farm_members TO authenticated; GRANT ALL ON public.farm_members TO service_role;
ALTER TABLE public.farm_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY member_read ON public.farm_members FOR SELECT TO authenticated USING(owner_id=auth.uid() OR user_id=auth.uid());
CREATE TABLE public.farm_invites (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, email text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','revoked')), expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.farm_invites TO authenticated; GRANT ALL ON public.farm_invites TO service_role;
ALTER TABLE public.farm_invites ENABLE ROW LEVEL SECURITY;
CREATE POLICY invite_read ON public.farm_invites FOR SELECT TO authenticated USING(owner_id=auth.uid());
CREATE TABLE public.farm_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, actor_id uuid NOT NULL, action text NOT NULL, details text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.farm_audit TO authenticated; GRANT ALL ON public.farm_audit TO service_role;
ALTER TABLE public.farm_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_read ON public.farm_audit FOR SELECT TO authenticated USING(owner_id=auth.uid());
CREATE TABLE public.push_devices (user_id uuid NOT NULL, token text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,token));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.push_devices TO authenticated; GRANT ALL ON public.push_devices TO service_role;
ALTER TABLE public.push_devices ENABLE ROW LEVEL SECURITY;
CREATE POLICY device_own ON public.push_devices FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE FUNCTION public.farm_access(_owner uuid,_table text,_data jsonb DEFAULT '{}') RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT (_owner=auth.uid() AND public.kuku_role()='owner') OR (EXISTS(SELECT 1 FROM public.farm_members WHERE owner_id=_owner AND user_id=auth.uid()) AND _table NOT IN ('customers','sales','salePayments','expenses','expensePayments','cashLogs','documents','auditLog','user_roles','staffPayments') AND NOT (_table='moduleRecords' AND _data->>'feature' IN ('house','farmProfile'))) $$;
REVOKE ALL ON FUNCTION public.farm_access(uuid,text,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.farm_access(uuid,text,jsonb) TO authenticated;
DROP POLICY records_read ON public.record_store; DROP POLICY records_insert ON public.record_store; DROP POLICY records_update ON public.record_store; DROP POLICY records_delete ON public.record_store;
CREATE POLICY records_read ON public.record_store FOR SELECT TO authenticated USING(public.farm_access(owner_id,table_name,data) OR (table_name='moduleRecords' AND data->>'feature' IN ('house','farmProfile') AND EXISTS(SELECT 1 FROM public.farm_members WHERE owner_id=record_store.owner_id AND user_id=auth.uid())));
CREATE POLICY records_insert ON public.record_store FOR INSERT TO authenticated WITH CHECK(public.farm_access(owner_id,table_name,data));
CREATE POLICY records_update ON public.record_store FOR UPDATE TO authenticated USING(public.farm_access(owner_id,table_name,data)) WITH CHECK(public.farm_access(owner_id,table_name,data));
CREATE POLICY records_delete ON public.record_store FOR DELETE TO authenticated USING(owner_id=auth.uid() AND public.kuku_role()='owner');
CREATE FUNCTION public.farm_invite_manager(_email text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN IF public.kuku_role() IS DISTINCT FROM 'owner' THEN RAISE EXCEPTION 'Owner access required'; END IF; IF _email !~* '^[^@ ]+@[^@ ]+\.[^@ ]+$' THEN RAISE EXCEPTION 'Enter a valid email'; END IF; INSERT INTO public.farm_invites(owner_id,email) VALUES(auth.uid(),lower(trim(_email))) RETURNING id INTO result; INSERT INTO public.farm_audit(owner_id,actor_id,action,details) VALUES(auth.uid(),auth.uid(),'Invited manager',lower(trim(_email))); RETURN result; END $$;
CREATE FUNCTION public.farm_pending_invites() RETURNS SETOF public.farm_invites LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT i.* FROM public.farm_invites i JOIN auth.users u ON u.id=auth.uid() AND lower(u.email)=i.email AND u.email_confirmed_at IS NOT NULL WHERE i.status='pending' AND i.expires_at>now() $$;
CREATE FUNCTION public.farm_accept_invite(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.farm_invites; BEGIN SELECT * INTO i FROM public.farm_invites WHERE id=_id AND status='pending' AND expires_at>now() FOR UPDATE; IF i.id IS NULL OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=auth.uid() AND lower(email)=i.email AND email_confirmed_at IS NOT NULL) THEN RAISE EXCEPTION 'A verified matching email is required'; END IF; IF i.owner_id=auth.uid() THEN RAISE EXCEPTION 'You already own this farm'; END IF; INSERT INTO public.farm_members(owner_id,user_id) VALUES(i.owner_id,auth.uid()) ON CONFLICT DO NOTHING; UPDATE public.farm_invites SET status='accepted' WHERE id=_id; INSERT INTO public.farm_audit(owner_id,actor_id,action,details) VALUES(i.owner_id,auth.uid(),'Accepted manager invitation',i.email); END $$;
CREATE FUNCTION public.farm_revoke(_id uuid,_invite boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF public.kuku_role() IS DISTINCT FROM 'owner' THEN RAISE EXCEPTION 'Owner access required'; END IF; IF _invite THEN UPDATE public.farm_invites SET status='revoked' WHERE id=_id AND owner_id=auth.uid(); ELSE DELETE FROM public.farm_members WHERE user_id=_id AND owner_id=auth.uid(); END IF; INSERT INTO public.farm_audit(owner_id,actor_id,action,details) VALUES(auth.uid(),auth.uid(),'Revoked access',_id::text); END $$;
REVOKE ALL ON FUNCTION public.farm_invite_manager(text), public.farm_pending_invites(),public.farm_accept_invite(uuid),public.farm_revoke(uuid,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.farm_invite_manager(text),public.farm_pending_invites(),public.farm_accept_invite(uuid),public.farm_revoke(uuid,boolean) TO authenticated;
CREATE FUNCTION public.farm_record_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.farm_audit(owner_id,actor_id,action,details) VALUES(NEW.owner_id,coalesce(auth.uid(),NEW.owner_id),TG_OP||' '||NEW.table_name,NEW.id); RETURN NEW; END $$;
CREATE TRIGGER farm_record_audit AFTER INSERT OR UPDATE ON public.record_store FOR EACH ROW EXECUTE FUNCTION public.farm_record_audit();